export const freshTutorial=()=>({status:'new',step:0,mode:'guided',tipsSeen:[]});
const lessons=[
 ['Welcome, network builder!','Take passengers to any stop matching their small symbol. Circles and squares start the game; triangles join in round 3. Shapes repeat across cities. Connect stops and keep queues moving.','Next: build your first bus route','map'],
 ['Buy your first bus','Bus is selected in the bottom-left dock. Drag from London to Oxford, then release on the stop. This costs your starting 20 credits. On a keyboard, open London and choose “Build a route from here”, then Oxford.','Drag London → Oxford','route'],
 ['Start the service','Press Play below the map. Each vehicle starts with one seat. Passengers get off first, then board one at a time. Each takes 0.5 seconds at a level-1 stop. Station upgrades make this faster.','Press Play','play'],
 ['Earn your first fares','Watch the bus carry passengers to their matching stops. Each delivery earns 3 credits. Your first three deliveries also earn a one-time 11-credit training grant to connect Bristol. After three deliveries, we will pause so you can expand. If paused, press Play again.','Deliver 3 passengers','passengers'],
 ['Connect Bristol','You now have enough credits for another bus. Drag Oxford → Bristol. Passengers can transfer between routes to reach a stop farther away.','Drag Oxford → Bristol','route'],
 ['Finish your first round','Press Play again. Deliver all five passengers to finish round 1. You can pause at any time to plan your network.','Deliver all 5 passengers','play'],
 ['Learn geography for credits','Glowing quiz coins appear during play. Tap one and answer a question about your newest area for 15 credits. The Country atlas button shows unlocked flags, capitals, landmarks and waterways. Reading pauses the game.','Explore the coin and atlas buttons whenever you like','geography'],
 ['Upgrade your network','Tap a stop for station upgrades and, later, harbour or airport construction. Press the circled i on a vehicle for its stats and fleet upgrades. Extra seats and speed help you clear queues.','Try a stop or a vehicle’s i button','upgrade'],
 ['Plan for the next round','At round end choose one benefit and one challenge, each from three cards. Their effects last for the run. Queues that wait too long blink red: clear them before the countdown ends. You can sell routes and rebuild; Retry restores the round-start budget.','One good card + one bad card','cards'],
 ['Your world will grow','Fog clears as new countries unlock. Trains arrive in round 8, ferries in 10, flights in 13, Channel Tunnel trains in 18 and high-speed trains in 20. Use zoom, Fit map and drag the water to pan. Come back to Tutorial whenever you need help.','You are ready to explore!','map']
];
const unlockTips={3:['Triangles join the network','Manchester introduces triangles. Circles, squares and triangles repeat across cities: take each passenger to any stop with the matching shape.'],4:['Wales is open','Connect its new stops by bus. Open the Country atlas to learn about Cardiff and Welsh landmarks.'],8:['Regular trains unlocked','Choose Train in the dock. Trains link stops on the same land, cost 55 base credits and have their own fleet upgrades.'],10:['Ferries and Ireland unlocked','Boats link two harbours on different land. Tap coastal stops to build more harbours. Northern Ireland is part of the UK; the Republic of Ireland is a separate country.'],13:['Flights unlocked','Flights need airports at both ends. Tap a stop to build an airport, then select Flight and drag between airports.'],18:['Channel Tunnel unlocked','Tunnel trains link Folkestone and Coquelles only. Connect buses or trains at the terminals for onward journeys.'],20:['High-speed trains unlocked','Select High-speed train for faster land routes. They have separate fleet upgrades and also use your train card bonuses.']};
export function observeTutorial(state){const t=state.tutorial;if(t?.status!=='active'||t.mode!=='guided')return false;const route=(a,b)=>state.links.some(l=>l.a===a&&l.b===b||l.a===b&&l.b===a);let advance=t.step===1&&route(0,1)||t.step===2&&state.running||t.step===3&&state.delivered>=3||t.step===4&&route(1,2)||t.step===5&&state.complete;if(!advance)return false;t.step++;if(t.step===4)state.running=false;return true;}
export function installTutorial({root,map,side,controls,state,node,refresh}){
 state.tutorial??=freshTutorial();let resumeTour=false,renderKey='',highlight=null;
 const panel=node('aside',null,'coastal-tutorial');panel.setAttribute('aria-label','Game tutorial');side.prepend(panel);
 const launch=node('button','? Tutorial');launch.type='button';launch.className='coastal-tutorial-launch';launch.onclick=()=>{resumeTour=state.running;state.running=false;state.tutorial.status='active';state.tutorial.step=0;state.tutorial.mode=state.round===1&&state.delivered===0&&state.links.length===0?'guided':'tour';renderKey='';refresh();panel.scrollIntoView({block:'nearest'});};controls.append(launch);
 function stop(status){state.tutorial.status=status;if(state.tutorial.mode==='tour'&&resumeTour&&!state.complete&&!state.failed)state.running=true;resumeTour=false;refresh();}
 function button(label,action){const b=node('button',label);b.type='button';b.onclick=action;return b;}
 function illustration(kind){const pic=node('div',null,'coastal-tutorial-picture');pic.setAttribute('aria-hidden','true');const icons={map:'🇬🇧  🧭  🌍',route:'◯ ━ 🚌 ━ □',play:'▶  🚌  →  □',passengers:'◯  🚌  →  +3',geography:'🪙  ?  🌍',upgrade:'🚌  ⓘ  ↑',cards:'✓  🃏  ⚠'};pic.textContent=icons[kind];return pic;}
 function clearHighlight(){highlight?.classList.remove('coastal-tutorial-target');highlight=null;}
 function refreshTutorial(){observeTutorial(state);const t=state.tutorial,tip=unlockTips[state.round],showTip=t.status!=='active'&&tip&&!t.tipsSeen.includes(state.round),key=[t.status,t.step,t.mode,state.round,showTip].join('|');if(key===renderKey)return;renderKey=key;clearHighlight();panel.replaceChildren();panel.hidden=t.status!=='new'&&t.status!=='active'&&!showTip;if(panel.hidden)return;
  if(showTip){panel.append(node('strong',tip[0]),node('p',tip[1]),button('Got it',()=>{t.tipsSeen.push(state.round);refresh();}));return;}
  if(t.status==='new'){panel.append(node('strong','New to Coastal Connections?'),node('p','Learn by building your first network.'),button('Start tutorial',()=>launch.click()),button('Skip for now',()=>stop('skipped')));return;}
  const [title,body,action,kind]=lessons[t.step];panel.append(node('span',(t.mode==='guided'?'LEARN BY PLAYING':'GAME WALKTHROUGH')+' · '+(t.step+1)+' / '+lessons.length,'coastal-tutorial-progress'),illustration(kind),node('h4',title),node('p',body));const gated=t.mode==='guided'&&t.step>=1&&t.step<=5;panel.append(node('strong',gated?'Your task: '+action:action,'coastal-tutorial-action'));if(!gated)panel.append(button(t.step===lessons.length-1?'Finish tutorial':'Next →',()=>{if(t.step===lessons.length-1)stop('done');else{t.step++;refresh();}}));else panel.append(node('small','This step advances when you do the task.'));panel.append(button('Skip tutorial',()=>stop('skipped')));
  const selector=t.step===2||t.step===5?'.coastal-controls button':t.step===6?'.coastal-atlas-button':t.step===7?'[data-vehicle-info="road"]':t.step===9?'.coastal-map-tools':null;highlight=selector?root.querySelector(selector):null;highlight?.classList.add('coastal-tutorial-target');
 }
 return {refresh:refreshTutorial,draw(ctx,stops){const t=state.tutorial;if(t.status!=='active'||t.mode!=='guided'||![1,4].includes(t.step))return;const [a,b]=t.step===1?[stops[0],stops[1]]:[stops[1],stops[2]];ctx.save();ctx.strokeStyle='#e7b431';ctx.lineWidth=4;ctx.setLineDash([6,7]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.setLineDash([]);for(const stop of [a,b]){ctx.beginPath();ctx.arc(stop.x,stop.y,30,0,Math.PI*2);ctx.stroke();}ctx.restore();},destroy:clearHighlight};
}
